    return 0;
}

#include <iostream>
#include <string>
using namespace std;

void printBar(string name, int length) {
    cout << name << " | ";
    for (int i = 1; i <= length; i++) {
        cout << "#";
    }
    cout << endl;
}

void greet(string name, int times) {
    for (int i = 1; i <= times; i++) {
        cout << "Hello, " << name << "!" << endl;
    }
}

int main() {
    printBar("Amara", 9);
    printBar("Sam", 4);
    greet("Mia", 3);
    return 0;
}

