#include <iostream>
#include <string>
using namespace std;

void printBar(string label, int length) {
    cout << label << " | ";
    for (int i = 1; i <= length; i++) {
        cout << "#";
    }
    cout << endl;
}

void describe(int score) {
    if (score >= 75) {
        cout << "Excellent." << endl;
    } else if (score >= 40) {
        cout << "A pass." << endl;
    } else {
        cout << "Needs work." << endl;
    }
}

int main() {
    cout << "Name? ";
    string name;
    getline(cin, name);

    cout << "Score out of 100? ";
    int score;
    cin >> score;

    printBar(name, score / 10);
    describe(score);
    return 0;
}

