#include <iostream>
using namespace std;

void printBar(int length, char symbol = '*') {
    for (int i = 1; i <= length; i++) {
        cout << symbol;
    }
    cout << endl;
}

int main() {
    printBar(7);          // symbol uses its default, '*'
    printBar(7, '#');     // symbol is '#' this time
    printBar(3, '=');
    return 0;
}

